#include <cstdio>
#include <memory>
#include <string>
#include <vector>

struct Event { bool begin; std::string name; double time; };

namespace
{
    struct Node
    {
        std::string name;
        double total{ 0 };
        int calls{ 0 };
        std::vector<std::unique_ptr<Node>> children;

        Node* child(const std::string& n)
        {
            for (auto& c : children) if (c->name == n) return c.get();
            children.push_back(std::make_unique<Node>());
            children.back()->name = n;
            return children.back().get();
        }
    };

    void print(const Node& n, int depth, std::vector<std::string>& out)
    {
        double childTotal{ 0 };
        for (const auto& c : n.children) childTotal += c->total;
        char buffer[160];
        std::snprintf(buffer, sizeof(buffer), "%s total %.1f self %.1f", n.name.c_str(), n.total, n.total - childTotal);
        std::string line{ std::string(static_cast<std::size_t>(depth) * 2, ' ') + buffer };
        if (n.calls > 1) line += " (" + std::to_string(n.calls) + " calls)";
        out.push_back(line);
        for (const auto& c : n.children) print(*c, depth + 1, out);
    }
}

std::vector<std::string> profileRows(const std::vector<Event>& events)
{
    Node root;
    struct Open { Node* node; double start; };
    std::vector<Open> stack;
    for (const Event& e : events)
    {
        if (e.begin)
        {
            Node* parent{ stack.empty() ? &root : stack.back().node };
            stack.push_back({ parent->child(e.name), e.time });
        }
        else
        {
            if (stack.empty()) return { "unbalanced events" };
            Open o{ stack.back() };
            stack.pop_back();
            o.node->total += e.time - o.start;
            ++o.node->calls;
        }
    }
    if (!stack.empty()) return { "unbalanced events" };
    std::vector<std::string> out;
    for (const auto& c : root.children) print(*c, 0, out);
    return out;
}

