using Lines = std::vector<std::string>;
const std::vector<Event> frame{
    { true, "frame", 0 }, { true, "update", 10 }, { true, "physics", 12 }, { false, "physics", 40 },
    { true, "think", 41 }, { false, "think", 52 }, { true, "think", 52 }, { false, "think", 60 }, { false, "update", 61 },
    { true, "render", 61 }, { false, "render", 150 }, { false, "frame", 152 },
};
TEST("the example") { CHECK_EQ(profileRows(frame), (Lines{ "frame total 152.0 self 12.0", "  update total 51.0 self 4.0", "    physics total 28.0 self 28.0", "    think total 19.0 self 19.0 (2 calls)", "  render total 89.0 self 89.0" })); }
TEST("merging merges children") {
    const std::vector<Event> e{ { true, "a", 0 }, { true, "b", 1 }, { false, "b", 2 }, { false, "a", 3 }, { true, "a", 10 }, { true, "b", 11 }, { false, "b", 14 }, { false, "a", 15 } };
    CHECK_EQ(profileRows(e), (Lines{ "a total 8.0 self 4.0 (2 calls)", "  b total 4.0 self 4.0 (2 calls)" }));
}
TEST("same name, different parents") {
    const std::vector<Event> e{ { true, "x", 0 }, { true, "load", 0 }, { false, "load", 1 }, { false, "x", 2 }, { true, "y", 2 }, { true, "load", 2 }, { false, "load", 5 }, { false, "y", 5 } };
    CHECK_EQ(profileRows(e), (Lines{ "x total 2.0 self 1.0", "  load total 1.0 self 1.0", "y total 3.0 self 0.0", "  load total 3.0 self 3.0" }));
}
TEST("unbalanced") { CHECK_EQ(profileRows({ { false, "a", 1 } }), (Lines{ "unbalanced events" })); CHECK_EQ(profileRows({ { true, "a", 1 } }), (Lines{ "unbalanced events" })); }
TEST("nothing") { CHECK(profileRows({}).empty()); }

